            if try child.teaqlIsCancelledNew() { continue }
            try child.teaqlAttachRoot(entity.teaqlEntityRoot)
            if child.tenant != entity.teaqlPreflightID {
                child.teaqlSetTenant(entity.teaqlPreflightID)
            }
            let childReason = child.teaqlEntityRoot.localAuditReason(child.teaqlEntityKey) ?? reason
            do {
                // Evaluate every child, even when the owner already has work.
                let childPending = try OrderItemAudited(entity: child, reason: childReason).teaqlValidateInputGraph()
                if childPending { pending = true }
            } catch let error as CheckException {
                let prefix = ObjectLocation.property("order_item_list").index(index)
                throw CheckException(error.violations.map { violation in
                    violation.prefixed(by: prefix)
                })
            }
        }
        return pending
    }

    func teaqlPreflightGraph(_ context: UserContext, session: GraphMutationSession) throws {
        guard try session.visitEntity(entity, phase: .preflight) else { return }
        if try entity.teaqlIsCancelledNew() { return }
        if entity.version != 0 && !entity.teaqlEntityRoot.isNew(entity.teaqlEntityKey)
            && entity.teaqlEntityRoot.hasPending(entity.teaqlEntityKey) {
            if !entity.isLoaded(Tenant.__TeaqlFields.ID_PROPERTY_member) {
                throw CheckException([CheckResult(ruleID: "invalid_type", location: .property(Tenant.__TeaqlFields.ID_PROPERTY_model), message: "Mutation requires a fully loaded entity", entityType: "Tenant")])
            }
            if !entity.isLoaded(Tenant.__TeaqlFields.NAME_PROPERTY_member) {
                throw CheckException([CheckResult(ruleID: "invalid_type", location: .property(Tenant.__TeaqlFields.NAME_PROPERTY_model), message: "Mutation requires a fully loaded entity", entityType: "Tenant")])
            }
            if !entity.isLoaded(Tenant.__TeaqlFields.VERSION_PROPERTY_member) {
                throw CheckException([CheckResult(ruleID: "invalid_type", location: .property(Tenant.__TeaqlFields.VERSION_PROPERTY_model), message: "Mutation requires a fully loaded entity", entityType: "Tenant")])
            }
        }
        try AuditedEntity(entity: entity, reason: reason).preflight(context)
        for (index, var child) in entity.purchaseOrderList.enumerated() {
            if try child.teaqlIsCancelledNew() {
                try PurchaseOrderAudited(entity: child, reason: reason).teaqlPreflightGraph(context, session: session)
                continue
            }
            try child.teaqlAttachRoot(entity.teaqlEntityRoot)
            if child.tenant != entity.teaqlPreflightID {
                child.teaqlSetTenant(entity.teaqlPreflightID)
            }
            let childReason = child.teaqlEntityRoot.localAuditReason(child.teaqlEntityKey) ?? reason
            if entity.id == 0 {
                try context.bindGraphReference(child, field: "tenant", to: entity)
            }
            do { try PurchaseOrderAudited(entity: child, reason: childReason).teaqlPreflightGraph(context, session: session) }
            catch let error as CheckException {
                let prefix = ObjectLocation.property("purchase_order_list").index(index)
                throw CheckException(context.translateCheckResults(error.violations.map { violation in
                    violation.prefixed(by: prefix)
                }))
            }
        }
        for (index, var child) in entity.orderItemList.enumerated() {
            if try child.teaqlIsCancelledNew() {
                try OrderItemAudited(entity: child, reason: reason).teaqlPreflightGraph(context, session: session)
                continue
            }
            try child.teaqlAttachRoot(entity.teaqlEntityRoot)
            if child.tenant != entity.teaqlPreflightID {
                child.teaqlSetTenant(entity.teaqlPreflightID)
            }
            let childReason = child.teaqlEntityRoot.localAuditReason(child.teaqlEntityKey) ?? reason
            if entity.id == 0 {
                try context.bindGraphReference(child, field: "tenant", to: entity)
            }
            do { try OrderItemAudited(entity: child, reason: childReason).teaqlPreflightGraph(context, session: session) }
            catch let error as CheckException {
                let prefix = ObjectLocation.property("order_item_list").index(index)
                throw CheckException(context.translateCheckResults(error.violations.map { violation in
                    violation.prefixed(by: prefix)
                }))
            }
        }
    }
